package com.mamtrex.hospital.admission;
import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="admissions") public class Admission extends BaseEntity { private String patientId; private String admittedAt; private String dischargedAt; private String reason; private String status; protected Admission(){} public Admission(String patientId, String admittedAt, String dischargedAt, String reason, String status){this.patientId=patientId; this.admittedAt=admittedAt; this.dischargedAt=dischargedAt; this.reason=reason; this.status=status;} public String getPatientId(){return patientId;} public String getAdmittedAt(){return admittedAt;} public String getDischargedAt(){return dischargedAt;} public String getReason(){return reason;} public String getStatus(){return status;} }
